// Drives Chrome over raw CDP to force a genuine narrow viewport (headless
// Chrome's --window-size silently floors below ~500px) and capture a real
// screenshot + a layout-overflow probe.
const PORT = process.argv[2] || 9333;
const URL_ = process.argv[3];
const WIDTH = parseInt(process.argv[4] || '360', 10);
const HEIGHT = parseInt(process.argv[5] || '780', 10);
const OUT = process.argv[6];

const listResp = await fetch(`http://localhost:${PORT}/json/new?${encodeURIComponent(URL_)}`, { method: 'PUT' });
const target = await listResp.json();
const wsUrl = target.webSocketDebuggerUrl;

const ws = new WebSocket(wsUrl);
let id = 0;
const pending = new Map();
function send(method, params = {}) {
  return new Promise((resolve) => {
    const msgId = ++id;
    pending.set(msgId, resolve);
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
}
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg.result);
    pending.delete(msg.id);
  }
});

await new Promise((r) => ws.addEventListener('open', r));

await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', {
  width: WIDTH, height: HEIGHT, deviceScaleFactor: 1, mobile: true,
});
await send('Page.navigate', { url: URL_ });
await new Promise((r) => setTimeout(r, 1200)); // let fonts/layout/JS settle

const evalResult = await send('Runtime.evaluate', {
  expression: `JSON.stringify({innerWidth, scrollWidth: document.documentElement.scrollWidth, scrollHeight: document.documentElement.scrollHeight})`,
  returnByValue: true,
});
console.error('LAYOUT:', evalResult.result.value);

const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
const fs = await import('node:fs');
fs.writeFileSync(OUT, Buffer.from(shot.data, 'base64'));
console.error('wrote', OUT);

await send('Target.closeTarget', { targetId: target.id });
ws.close();
process.exit(0);

